#include <iostream>
using namespace std;

// Simple recursion example: countdown
void countdown(int n) {
    if (n <= 0) {  // Base case
        cout << "Go!" << endl;
        return;
    }
    cout << n << endl;
    countdown(n - 1);  // Recursive case
}

int main() {
    countdown(5);
    return 0;
}

