using namespace std;

void headRecursion(int n) {
    if (n == 0) return;
    headRecursion(n - 1);  // head call
    cout << n << " ";
}

void tailRecursion(int n) {
    if (n == 0) return;
    cout << n << " ";
    tailRecursion(n - 1);  // tail call
}

int fib(int n) {
    if (n <= 1) return n;
    return fib(n - 1) + fib(n - 2);  // two recursive calls
}

int main() {
    headRecursion(5); cout << endl;
    tailRecursion(5); cout << endl;
    cout << fib(6) << endl;
    return 0;
}

