#include <iostream>
#include <vector>
using namespace std;

void subsets(vector<int>& nums, int idx, vector<int>& curr, vector<vector<int>>& result) {
    result.push_back(curr);
    for (int i = idx; i < (int)nums.size(); i++) {
        curr.push_back(nums[i]);       // choose
        subsets(nums, i + 1, curr, result);  // explore
        curr.pop_back();               // unchoose (backtrack)
    }
}

int main() {
    vector<int> nums = {1, 2, 3};
    vector<int> curr;
    vector<vector<int>> result;
    subsets(nums, 0, curr, result);
    for (auto& s : result) {
        for (int x : s) cout << x << " ";
        cout << endl;
    }
    return 0;
}

