#include <iostream>
using namespace std;

long long factorial(int n) {
    if (n == 0) return 1;
    return n * factorial(n - 1);
}

int fib(int n) {
    if (n <= 1) return n;
    return fib(n - 1) + fib(n - 2);
}

long long power(long long x, int n) {
    if (n == 0) return 1;
    if (n % 2 == 0) {
        long long half = power(x, n / 2);
        return half * half;
    }
    return x * power(x, n - 1);
}

int main() {
    cout << factorial(5) << endl;  // 120
    cout << fib(7) << endl;        // 13
    cout << power(2, 10) << endl;  // 1024
    return 0;
}

